from typing import List
import heapq

class Solution:
    def findMaxSum(self, nums1: List[int], nums2: List[int], k: int) -> List[int]:
        n = len(nums1)
        indices = list(range(n))
        indices.sort(key=lambda i: nums1[i])

        ans = [0] * n
        heap = []
        current_sum = 0

        i = 0
        while i < n:
            j = i
            while j < n and nums1[indices[j]] == nums1[indices[i]]:
                ans[indices[j]] = current_sum
                j += 1

            for p in range(i, j):
                val = nums2[indices[p]]
                heapq.heappush(heap, val)
                current_sum += val

                if len(heap) > k:
                    current_sum -= heapq.heappop(heap)

            i = j

        return ans
